import { posix } from "node:path";
import { Data, Effect } from "effect";
import {
  fileRouteModuleExportName,
  fileRouteSupportModules,
  type FileRouteManifest,
  type FileRouteManifestEntry,
  type FileRouteManifestModule,
} from "./file-routes.js";

/** Options that control how generated file-route definitions import route modules. */
export interface FileRouteDefinitionsModuleOptions {
  /** Generated file location used as the base for relative imports. */
  readonly generatedFile?: string;
  /** Whether generated imports are relative to the generated file or root-absolute. */
  readonly importMode?: "relative" | "rootAbsolute";
}

/** Options for the complete generated route definitions module artifact. */
export interface GeneratedFileRouteDefinitionsModuleOptions extends FileRouteDefinitionsModuleOptions {
  /** Header emitted before generated TypeScript. */
  readonly header?: string;
}

/** Error raised when a route id cannot become a valid generated TypeScript identifier. */
export class FileRouteDefinitionsModuleInvalidIdentifier extends Data.TaggedError(
  "FileRouteDefinitionsModuleInvalidIdentifier",
)<{
  readonly routeId: string;
  readonly routePath: string;
}> {}

/** Error raised when a manifest module export name is not a valid identifier. */
export class FileRouteDefinitionsModuleInvalidExportName extends Data.TaggedError(
  "FileRouteDefinitionsModuleInvalidExportName",
)<{
  readonly exportName: string;
}> {}

/** Typed failures that can occur while creating generated route definitions. */
export type FileRouteDefinitionsModuleError =
  | FileRouteDefinitionsModuleInvalidIdentifier
  | FileRouteDefinitionsModuleInvalidExportName;

/** Default generated-file header for Start route definitions artifacts. */
export const defaultGeneratedFileRouteDefinitionsHeader =
  "// oxfmt-disable\n// This file is generated by @sunfall/arc-start. Do not edit.";
const defaultGeneratedFile = "src/routeTree.gen.ts";
const identifierPattern = /^[A-Za-z_$][A-Za-z0-9_$]*$/;
const generatedLineMaxLength = 100;

/** Generated import reference for one route module and its optional lazy component. */
interface RouteModuleReference {
  readonly entry: FileRouteManifestEntry;
  readonly identifier: string;
  readonly importSpecifier: string;
  /** Lazy import specifier of the route's sibling `*.component` module, when it has one. */
  readonly componentSpecifier?: string;
}

/** Generated import reference for a layout, error boundary, or metadata module. */
interface SupportModuleReference {
  readonly module: FileRouteManifestModule;
  readonly identifier: string;
  readonly importSpecifier: string;
}

const checkedIdentifier = (identifier: string, routeId: string, routePath: string): string => {
  if (!identifierPattern.test(identifier)) {
    throw new FileRouteDefinitionsModuleInvalidIdentifier({ routeId, routePath });
  }
  return identifier;
};

const identifierSegment = (value: string): string => {
  const segment = value
    .replace(/[^A-Za-z0-9_$]+/g, "_")
    .replace(/_+/g, "_")
    .replace(/^_+|_+$/g, "");
  return segment.length === 0 ? "module" : /^[A-Za-z_$]/.test(segment) ? segment : `_${segment}`;
};

const supportIdentifierPrefix = {
  Layout: "layout",
  ErrorBoundary: "errorBoundary",
  Metadata: "metadata",
  Component: "component",
  Route: "route",
} as const;

const supportModuleIdentifier = (module: FileRouteManifestModule, sourceScoped: boolean): string =>
  checkedIdentifier(
    sourceScoped
      ? `${supportIdentifierPrefix[module.kind]}_${identifierSegment(module.routeId)}_${identifierSegment(module.id)}`
      : `${supportIdentifierPrefix[module.kind]}_${module.routeId}`,
    module.routeId,
    module.routePath,
  );

const stringLiteral = (value: string): string => JSON.stringify(value);

const propertyKeyLiteral = (value: string): string =>
  identifierPattern.test(value) ? value : stringLiteral(value);

const oneLineOrSplit = (oneLine: string, splitLines: readonly string[]): readonly string[] =>
  oneLine.length <= generatedLineMaxLength ? [oneLine] : splitLines;

const objectEntryLines = (key: string, value: string): readonly string[] =>
  oneLineOrSplit(`  ${key}: ${value},`, [`  ${key}:`, `    ${value},`]);

const arrayEntryLines = (key: string, values: readonly string[]): readonly string[] =>
  oneLineOrSplit(`  ${key}: [${values.join(", ")}],`, [
    `  ${key}: [`,
    ...values.map((value) => `    ${value},`),
    "  ],",
  ]);

const importLines = (
  importName: string,
  identifier: string,
  importSpecifier: string,
): readonly string[] =>
  oneLineOrSplit(
    `import { ${importName} as ${identifier} } from ${stringLiteral(importSpecifier)};`,
    ["import {", `  ${importName} as ${identifier},`, `} from ${stringLiteral(importSpecifier)};`],
  );

/** `open values close` on one line when it fits, else one value per line. */
const listLines = (
  open: string,
  values: readonly string[],
  close: string,
  padding = "",
): readonly string[] =>
  oneLineOrSplit(`${open}${padding}${values.join(", ")}${padding}${close}`, [
    open,
    ...values.map((value) => `  ${value},`),
    close,
  ]);

const typeScriptLiteral = (value: unknown, depth: number = 0): string => {
  if (typeof value !== "object" || value === null) {
    return JSON.stringify(value);
  }
  const childIndent = "  ".repeat(depth + 1);
  const currentIndent = "  ".repeat(depth);
  if (Array.isArray(value)) {
    return value.length === 0
      ? "[]"
      : [
          "[",
          ...value.map((item) => `${childIndent}${typeScriptLiteral(item, depth + 1)},`),
          `${currentIndent}]`,
        ].join("\n");
  }
  const entries = Object.entries(value).filter(([, entryValue]) => entryValue !== undefined);
  if (entries.length === 0) {
    return "{}";
  }
  return [
    "{",
    ...entries.map(([key, entryValue]) => {
      const propertyKey = propertyKeyLiteral(key);
      const propertyValue = typeScriptLiteral(entryValue, depth + 1);
      const oneLine = `${childIndent}${propertyKey}: ${propertyValue},`;
      return propertyValue.includes("\n")
        ? oneLine
        : oneLineOrSplit(oneLine, [
            `${childIndent}${propertyKey}:`,
            `${childIndent}  ${propertyValue},`,
          ]).join("\n");
    }),
    `${currentIndent}}`,
  ].join("\n");
};

/** The runtime module path TypeScript resolves a source file through (`.ts` → `.js`). */
const runtimeModulePath = (moduleId: string): string =>
  posix
    .normalize((moduleId.split(/[?#]/, 1)[0] ?? moduleId).replace(/\\/g, "/"))
    .replace(/\.tsx?$/, ".js")
    .replace(/\.mts$/, ".mjs")
    .replace(/\.cts$/, ".cjs");

const moduleImportSpecifier = (
  module: Pick<FileRouteManifestEntry, "moduleId">,
  options: FileRouteDefinitionsModuleOptions,
): string => {
  const source = runtimeModulePath(module.moduleId);
  if (options.importMode === "rootAbsolute") {
    return source.startsWith("/") ? source : `/${source}`;
  }
  // Relative imports resolve root-relative: a leading slash on either side is ignored.
  const fromDirectory = posix.dirname(
    posix.normalize(options.generatedFile ?? defaultGeneratedFile).replace(/^\/+/, ""),
  );
  const specifier = posix.relative(fromDirectory, source.replace(/^\/+/, "")) || ".";
  return specifier.startsWith(".") ? specifier : `./${specifier}`;
};

const routeModuleReferences = (
  manifest: FileRouteManifest,
  options: FileRouteDefinitionsModuleOptions,
): readonly RouteModuleReference[] =>
  manifest.entries.map((entry) => {
    const component = manifest.modules.find(
      (module) => module.kind === "Component" && module.id === `${entry.id}.component`,
    );
    return {
      entry,
      identifier: checkedIdentifier(entry.routeId, entry.routeId, entry.routePath),
      importSpecifier: moduleImportSpecifier(entry, options),
      ...(component === undefined
        ? {}
        : { componentSpecifier: moduleImportSpecifier(component, options) }),
    };
  });

const supportModuleReferences = (
  modules: readonly FileRouteManifestModule[],
  options: FileRouteDefinitionsModuleOptions,
): readonly SupportModuleReference[] => {
  const baseCounts = new Map<string, number>();
  for (const module of modules) {
    const base = supportModuleIdentifier(module, false);
    baseCounts.set(base, (baseCounts.get(base) ?? 0) + 1);
  }
  return modules.map((module) => {
    if (!identifierPattern.test(module.exportName)) {
      throw new FileRouteDefinitionsModuleInvalidExportName({ exportName: module.exportName });
    }
    return {
      module,
      identifier: supportModuleIdentifier(
        module,
        (baseCounts.get(supportModuleIdentifier(module, false)) ?? 0) > 1,
      ),
      importSpecifier: moduleImportSpecifier(module, options),
    };
  });
};

const routeTypeLines: readonly string[] = [
  "/** Tuple type for the generated app-specific route tree. */",
  "export type RouteTree = typeof routes;",
  "/** Map type keyed by generated route id. */",
  "export type RouteById = typeof routeById;",
  "/** Union of generated route ids such as `route_projects_$id`. */",
  "export type FileRouteId = keyof RouteById;",
  "/** Params for each generated route id. */",
  "export type FileRouteParamsById = { readonly [Id in FileRouteId]: Route.Params<RouteById[Id]> };",
  "/** Search values for each generated route id. */",
  "export type FileRouteSearchById = { readonly [Id in FileRouteId]: Route.Search<RouteById[Id]> };",
  "/** Href options for each generated route id. */",
  "export type FileRouteHrefOptionsById = {",
  "  readonly [Id in FileRouteId]: Route.HrefOptions<RouteById[Id]>;",
  "};",
  "/** Href options for one generated route id. */",
  "export type FileRouteHrefOptions<Id extends FileRouteId> = FileRouteHrefOptionsById[Id];",
  "/** Href arguments for each generated route id. */",
  "export type FileRouteHrefArgsById = { readonly [Id in FileRouteId]: Route.HrefArgs<RouteById[Id]> };",
  "/** Href arguments for one generated route id. */",
  "export type FileRouteHrefArgs<Id extends FileRouteId> = FileRouteHrefArgsById[Id];",
  "/** Layout modules keyed by generated route id. */",
  "export type FileRouteLayoutsById = typeof fileRouteLayoutsById;",
  "/** Error boundary modules keyed by generated route id when present. */",
  "export type FileRouteErrorBoundaryById = typeof fileRouteErrorBoundaryById;",
  "/** Metadata modules keyed by generated route id. */",
  "export type FileRouteMetadataById = typeof fileRouteMetadataById;",
  "/** Layout modules for one generated route id. */",
  "export type FileRouteLayouts<Id extends FileRouteId> = FileRouteLayoutsById[Id];",
  "/** Error boundary module for one generated route id, or undefined when none is scoped. */",
  "export type FileRouteErrorBoundary<Id extends FileRouteId> =",
  "  Id extends keyof FileRouteErrorBoundaryById ? FileRouteErrorBoundaryById[Id] : undefined;",
  "/** Metadata modules for one generated route id. */",
  "export type FileRouteMetadataModules<Id extends FileRouteId> = FileRouteMetadataById[Id];",
  "/** Static metadata for all file-route modules discovered by Start. */",
  "export type FileRouteModules = typeof fileRouteModules;",
];

const routeDefinitionsSource = (
  manifest: FileRouteManifest,
  options: FileRouteDefinitionsModuleOptions,
): string => {
  const references = routeModuleReferences(manifest, options);
  const supportByEntry = manifest.entries.map((entry) => ({
    entry,
    ...fileRouteSupportModules(manifest, entry),
  }));
  const referencedSupport = new Set(
    supportByEntry
      .flatMap((support) => [
        ...support.layouts,
        ...(support.errorBoundary === undefined ? [] : [support.errorBoundary]),
        ...support.metadataModules,
      ])
      .map((module) => module.moduleId),
  );
  const supportReferences = supportModuleReferences(
    manifest.modules.filter(
      (module) =>
        module.kind !== "Route" &&
        module.kind !== "Component" &&
        referencedSupport.has(module.moduleId),
    ),
    options,
  );
  const supportIdentifier = new Map(
    supportReferences.map((reference) => [reference.module.moduleId, reference.identifier]),
  );
  const identifierFor = (module: FileRouteManifestModule): string =>
    supportIdentifier.get(module.moduleId)!;

  const routeIdentifiers = references.map(({ identifier }) => identifier);
  const routeImports = references.flatMap(({ identifier, importSpecifier, componentSpecifier }) =>
    importLines(
      fileRouteModuleExportName("Route"),
      componentSpecifier === undefined ? identifier : `${identifier}_definition`,
      importSpecifier,
    ),
  );
  const supportImports = supportReferences.flatMap(({ module, identifier, importSpecifier }) =>
    importLines(module.exportName, identifier, importSpecifier),
  );
  // A route with a sibling `*.component` module renders it from its own chunk.
  const componentRoutes = references.flatMap(({ identifier, componentSpecifier }) =>
    componentSpecifier === undefined
      ? []
      : [
          `const ${identifier} = Route.withComponent(`,
          `  ${identifier}_definition,`,
          ...oneLineOrSplit(
            `  Route.lazyComponent(Effect.tryPromise(() => import(${stringLiteral(componentSpecifier)}))),`,
            [
              "  Route.lazyComponent(",
              `    Effect.tryPromise(() => import(${stringLiteral(componentSpecifier)})),`,
              "  ),",
            ],
          ),
          ");",
        ],
  );
  const pathChecks = references.flatMap(({ entry, identifier }) =>
    oneLineOrSplit(
      `const ${identifier}_path: ${stringLiteral(entry.routePath)} = ${identifier}.path;`,
      [
        `const ${identifier}_path:`,
        `  ${stringLiteral(entry.routePath)} =`,
        `  ${identifier}.path;`,
      ],
    ),
  );
  // Runtime twin of the path checks: Vite builds do not type-check, so the
  // route tree also fails at module load when a route module's
  // `Route.define(path, ...)` disagrees with the path derived from its file.
  const pathAssertion =
    references.length === 0
      ? []
      : [
          "for (const [route, path, file] of [",
          ...references.flatMap(({ entry, identifier }) =>
            oneLineOrSplit(
              `  [${identifier}, ${stringLiteral(entry.routePath)}, ${stringLiteral(entry.filePath)}],`,
              [
                "  [",
                `    ${identifier},`,
                `    ${stringLiteral(entry.routePath)},`,
                `    ${stringLiteral(entry.filePath)},`,
                "  ],",
              ],
            ),
          ),
          "] as const) {",
          "  if ((route.path as string) !== path) {",
          "    throw new Error(",
          "      `${file} declares Route.define(${JSON.stringify(route.path)}), ` +",
          "        `but its file location maps to ${JSON.stringify(path)}.`,",
          "    );",
          "  }",
          "}",
          "",
        ];
  const errorBoundaryEntries = supportByEntry.flatMap(({ entry, errorBoundary }) =>
    errorBoundary === undefined
      ? []
      : objectEntryLines(propertyKeyLiteral(entry.routeId), identifierFor(errorBoundary)),
  );

  return [
    'import { Route } from "@sunfall/arc-core";',
    ...(componentRoutes.length > 0 ? ['import { Effect } from "effect";'] : []),
    "",
    ...routeImports,
    ...supportImports,
    ...(routeImports.length + supportImports.length > 0 ? [""] : []),
    ...(componentRoutes.length > 0 ? [...componentRoutes, ""] : []),
    ...pathChecks,
    ...(pathChecks.length > 0 ? ["", ...pathAssertion] : []),
    ...(routeIdentifiers.length > 0
      ? [...listLines("export {", routeIdentifiers, "};", " "), ""]
      : []),
    "/** Ordered app-specific route definitions discovered from Start file routes. */",
    ...listLines("export const routes = [", routeIdentifiers, "] as const;"),
    "/** Map from generated route id to the exact route definition for that file route. */",
    "export const routeById = {",
    ...routeIdentifiers.flatMap((identifier) =>
      objectEntryLines(propertyKeyLiteral(identifier), identifier),
    ),
    "} as const;",
    "",
    "/** Layout modules that wrap each generated route, ordered from source-scope root to leaf. */",
    "export const fileRouteLayoutsById = {",
    ...supportByEntry.flatMap(({ entry, layouts }) =>
      arrayEntryLines(propertyKeyLiteral(entry.routeId), layouts.map(identifierFor)),
    ),
    "} as const;",
    "/** Nearest source-scoped error boundary module for each generated route, when one exists. */",
    ...(errorBoundaryEntries.length === 0
      ? ["export const fileRouteErrorBoundaryById = {} as const;"]
      : ["export const fileRouteErrorBoundaryById = {", ...errorBoundaryEntries, "} as const;"]),
    "/** Metadata modules scoped to each generated route by source id, ordered from root to leaf. */",
    "export const fileRouteMetadataById = {",
    ...supportByEntry.flatMap(({ entry, metadataModules }) =>
      arrayEntryLines(propertyKeyLiteral(entry.routeId), metadataModules.map(identifierFor)),
    ),
    "} as const;",
    "/** Returns layout modules for a generated route id. */",
    "export const layoutsById = <Id extends FileRouteId>(id: Id): FileRouteLayouts<Id> =>",
    "  fileRouteLayoutsById[id];",
    "/** Returns the nearest error boundary module for a generated route id, when one exists. */",
    "export const errorBoundaryById = <Id extends FileRouteId>(id: Id): FileRouteErrorBoundary<Id> =>",
    "  (fileRouteErrorBoundaryById as Partial<Record<FileRouteId, unknown>>)[",
    "    id",
    "  ] as FileRouteErrorBoundary<Id>;",
    "/** Returns metadata modules for a generated route id. */",
    "export const metadataById = <Id extends FileRouteId>(id: Id): FileRouteMetadataModules<Id> =>",
    "  fileRouteMetadataById[id];",
    "",
    "/** Route, component, layout, error boundary, and metadata modules discovered by Start. */",
    `export const fileRouteModules = ${typeScriptLiteral(manifest.modules)} as const;`,
    "",
    ...routeTypeLines,
  ].join("\n");
};

/** Creates the TypeScript source for a route tree module from a file-route manifest. */
export const createFileRouteDefinitionsModule = (
  manifest: FileRouteManifest,
  options: FileRouteDefinitionsModuleOptions = {},
): Effect.Effect<string, FileRouteDefinitionsModuleError> =>
  Effect.suspend(() => {
    try {
      return Effect.succeed(routeDefinitionsSource(manifest, options));
    } catch (cause) {
      if (
        cause instanceof FileRouteDefinitionsModuleInvalidIdentifier ||
        cause instanceof FileRouteDefinitionsModuleInvalidExportName
      ) {
        return Effect.fail(cause);
      }
      throw cause;
    }
  });

/** Creates the full generated route definitions module including the configured header. */
export const createGeneratedFileRouteDefinitionsModule = (
  manifest: FileRouteManifest,
  options: GeneratedFileRouteDefinitionsModuleOptions = {},
): Effect.Effect<string, FileRouteDefinitionsModuleError> =>
  Effect.map(createFileRouteDefinitionsModule(manifest, options), (source) =>
    [options.header ?? defaultGeneratedFileRouteDefinitionsHeader, "", source, ""].join("\n"),
  );
